    {id:8,title:'De high tea',subtitle:'Gastvrij voor ouderen van Nolenshage',cook:null,theory:['h3','h4','h5'],type:'Eindopdracht · datum volgt',goal:'Je organiseert en verzorgt samen met de klas een gastvrije en veilige high tea.',blocks:[['Opbouwen','45 min','Keuken/zaal klaarzetten, materialen controleren, tafels indekken.'],['Voorbereiden','45 min','Gerechten en dranken klaarmaken, kwaliteit en allergenen controleren.'],['Gasten ontvangen','20 min','Gastvrij begroeten, begeleiden en passende plekken aanbieden.'],['High tea serveren','60 min','Eten en thee verzorgen, vragen beantwoorden, afruimen.'],['Opruimen en evalueren','40 min','Schoonmaken, gasten bedanken, rubric en terugblik.']],tasks:[['setup','Zaal en tafels veilig ingericht','Docent controleert'],['food','Gerechten en dranken gereed en gecheckt','Hygiëne / allergenen'],['welcome','Gasten van Nolenshage ontvangen','Gastvrijheid'],['own','Eigen taak zelfstandig uitgevoerd','Praktijkrubric high tea'],['serve','Eten en thee netjes geserveerd','Praktijkrubric high tea'],['clean','Alles opgeruimd en teruggegeven','Samenwerken'],['reflection','Reflectie en portfolio afgerond','Eindopdracht']]}
